var surfWeatherFunctionSchema = {
  name: "surfWeather",
  description: [
    "\u83B7\u53D6\u6307\u5B9A\u6D77\u5CB8\u4F4D\u7F6E\u7684\u51B2\u6D6A\u5929\u6C14\u9884\u62A5\uFF0C\u5305\u62EC\u6D6A\u9AD8\u3001\u6D8C\u6D6A\u9AD8\u5EA6\u3001\u6D6A\u5468\u671F\u3001\u6D8C\u6D6A\u5468\u671F\u3001\u6D6A\u5411\u7B49\u5173\u952E\u6307\u6807\u3002",
    "\u6570\u636E\u6765\u6E90\uFF1AOpen-Meteo Marine API\uFF08\u514D\u8D39\uFF0C\u65E0\u9700 API Key\uFF09\u3002",
    "\u9002\u7528\u573A\u666F\uFF1A\u67E5\u8BE2\u67D0\u4E2A\u51B2\u6D6A\u70B9\u672A\u6765\u51E0\u5929\u7684\u6D77\u6D6A\u72B6\u51B5\uFF0C\u5224\u65AD\u662F\u5426\u9002\u5408\u51B2\u6D6A\u3002"
  ].join("\n"),
  parameters: {
    type: "object",
    properties: {
      latitude: {
        type: "number",
        description: "\u7EAC\u5EA6\uFF0C\u4F8B\u5982\u6D77\u5357\u4E07\u5B81\u4E3A 18.8"
      },
      longitude: {
        type: "number",
        description: "\u7ECF\u5EA6\uFF0C\u4F8B\u5982\u6D77\u5357\u4E07\u5B81\u4E3A 110.4"
      },
      location_name: {
        type: "string",
        description: "\u5730\u70B9\u540D\u79F0\uFF08\u53EF\u9009\uFF09\uFF0C\u4EC5\u7528\u4E8E\u5C55\u793A\uFF0C\u4F8B\u5982\u300C\u6D77\u5357\u4E07\u5B81\u65E5\u6708\u6E7E\u300D"
      },
      forecast_days: {
        type: "number",
        description: "\u9884\u62A5\u5929\u6570\uFF0C1~7\uFF0C\u9ED8\u8BA4 3"
      }
    },
    required: ["latitude", "longitude"]
  }
};
function getSurfRating(waveHeight, wavePeriod) {
  if (waveHeight < 0.3) return "\u26AB \u65E0\u6D6A";
  if (waveHeight < 0.6 && wavePeriod < 6) return "\u{1F7E4} \u6781\u5DEE";
  if (waveHeight < 0.8) return "\u{1F534} \u5DEE";
  if (waveHeight < 1.2 && wavePeriod >= 6) return "\u{1F7E1} \u4E00\u822C";
  if (waveHeight < 2 && wavePeriod >= 8) return "\u{1F7E2} \u8F83\u597D";
  if (waveHeight >= 2 && wavePeriod >= 10) return "\u{1F535} \u4F18\u79C0";
  return "\u{1F7E1} \u4E00\u822C";
}
function getWindDirection(deg) {
  const dirs = ["\u5317", "\u4E1C\u5317", "\u4E1C", "\u4E1C\u5357", "\u5357", "\u897F\u5357", "\u897F", "\u897F\u5317"];
  return dirs[Math.round(deg / 45) % 8];
}
async function surfWeatherFunc(args) {
  const { latitude, longitude, location_name, forecast_days = 3 } = args;
  const days = Math.min(Math.max(Math.round(forecast_days), 1), 7);
  const params = [
    "wave_height",
    "wave_period",
    "wave_direction",
    "wind_wave_height",
    "swell_wave_height",
    "swell_wave_period",
    "swell_wave_direction"
  ].join(",");
  const url = `https://marine-api.open-meteo.com/v1/marine?latitude=${latitude}&longitude=${longitude}&hourly=${params}&timezone=Asia/Shanghai&forecast_days=${days}`;
  const res = await fetch(url);
  if (!res.ok) {
    throw new Error(`Open-Meteo API \u8BF7\u6C42\u5931\u8D25: ${res.status} ${res.statusText}`);
  }
  const data = await res.json();
  const h = data.hourly;
  const locationLabel = location_name || `${data.latitude}\xB0N, ${data.longitude}\xB0E`;
  const dailySummaries = [];
  const totalHours = h.time.length;
  for (let d = 0; d < days; d++) {
    const start = d * 24;
    const end = Math.min(start + 24, totalHours);
    let bestIdx = start;
    for (let i = start; i < end; i++) {
      const hour = parseInt(h.time[i].slice(11, 13), 10);
      if (hour < 8 || hour > 20) continue;
      if (h.wave_height[i] > h.wave_height[bestIdx]) bestIdx = i;
    }
    const date = h.time[bestIdx].slice(0, 10);
    const wh = h.wave_height[bestIdx];
    const wp = h.wave_period[bestIdx];
    const sh = h.swell_wave_height[bestIdx];
    const sp = h.swell_wave_period[bestIdx];
    const wd = h.wave_direction[bestIdx];
    dailySummaries.push({
      date,
      maxWaveHeight: wh,
      wavePeriod: wp,
      swellHeight: sh,
      swellPeriod: sp,
      waveDirection: wd,
      rating: getSurfRating(wh, wp)
    });
  }
  const lines = [];
  lines.push(`\u{1F3C4} \u51B2\u6D6A\u5929\u6C14\u9884\u62A5 \u2014 ${locationLabel}`);
  lines.push(`\u6570\u636E\u6765\u6E90\uFF1AOpen-Meteo Marine API
`);
  lines.push(`\u65E5\u671F          \u8BC4\u7EA7      \u6D6A\u9AD8    \u6D8C\u6D6A    \u5468\u671F  \u6D8C\u6D6A\u5468\u671F  \u6D6A\u5411`);
  lines.push("\u2500".repeat(58));
  for (const s of dailySummaries) {
    lines.push(
      `${s.date}  ${s.rating}  ${s.maxWaveHeight.toFixed(2)}m  ${s.swellHeight.toFixed(2)}m  ${s.wavePeriod.toFixed(1)}s  ${s.swellPeriod.toFixed(1)}s  ${getWindDirection(s.waveDirection)}`
    );
  }
  lines.push("\n\u8BC4\u7EA7\u8BF4\u660E\uFF1A\u{1F535}\u4F18\u79C0 \u{1F7E2}\u8F83\u597D \u{1F7E1}\u4E00\u822C \u{1F534}\u5DEE \u{1F7E4}\u6781\u5DEE \u26AB\u65E0\u6D6A");
  const displayData = lines.join("\n");
  return {
    rawData: {
      location: locationLabel,
      latitude: data.latitude,
      longitude: data.longitude,
      forecast_days: days,
      daily: dailySummaries,
      hourly: h
    },
    displayData
  };
}

