// packages/ai/tools/browserTools/common.ts
async function executeBrowserTool(toolName, parameters, thunkApi) {
  try {
    const result = await callToolApi(
      thunkApi,
      "/api/browser-tool",
      { toolName, params: parameters },
      { withAuth: true }
    );
    return result.data;
  } catch (error) {
    console.error(`\u6267\u884C\u6D4F\u89C8\u5668\u5DE5\u5177 '${toolName}' \u65F6\u53D1\u751F\u7F51\u7EDC\u6216\u89E3\u6790\u9519\u8BEF:`, error);
    throw new Error(`\u6D4F\u89C8\u5668\u5DE5\u5177 '${toolName}' \u5931\u8D25: ${error.message}`);
  }
}

