async function codeSearchFunc(args, thunkApi, context) {
  const baseUrl = getToolBaseUrl(thunkApi);
  const apiUrl = `${baseUrl}/api/code-search`;
  const mode = args.mode ?? "content";
  const response = await fetch(apiUrl, {
    method: "POST",
    headers: buildToolRequestHeaders(thunkApi, {
      withAuth: true,
      agentKey: context?.agentKey
    }),
    signal: context?.signal,
    body: JSON.stringify({
      query: args.query,
      path: args.path ?? args.pathScope,
      glob: args.glob,
      mode,
      maxResults: args.maxResults ?? args.maxFiles,
      caseSensitive: args.caseSensitive
    })
  });
  const responseText = await response.text();
  let data = null;
  try {
    data = responseText ? JSON.parse(responseText) : {};
  } catch {
    data = null;
  }
  if (!response.ok || data?.error) {
    throw new Error(
      data?.error || `codeSearch \u8BF7\u6C42\u5931\u8D25: ${response.status}${responseText ? `. \u54CD\u5E94: ${responseText}` : ""}`
    );
  }
  if (mode === "files") {
    const files = Array.isArray(data.files) ? data.files : [];
    return {
      rawData: data,
      displayData: `\u{1F4C1} codeSearch \u5217\u51FA ${files.length} \u4E2A\u6587\u4EF6${data.truncated ? "\uFF08\u5DF2\u622A\u65AD\uFF09" : ""}`
    };
  }
  const hits = Array.isArray(data.hits) ? data.hits : [];
  return {
    rawData: data,
    displayData: `\u{1F50D} codeSearch \u627E\u5230 ${hits.length} \u6761\u5339\u914D${data.truncated ? "\uFF08\u5DF2\u622A\u65AD\uFF09" : ""}`
  };
}

