async function resolveCfBrowserUrl(url) {
  if (!url) {
    return {
      targetUrl: url,
      originalUrl: url,
      rewritten: false
    };
  }
  const resolution = await discoverCanonicalDocsUrl(url);
  const targetUrl = resolution.resolvedUrl;
  await assertFetchableDocsUrl(targetUrl, fetch, url);
  return {
    targetUrl,
    originalUrl: url,
    rewritten: targetUrl !== url
  };
}
