async function appVersionListFunc(args, thunkApi) {
  const { appId } = args;
  if (!appId) throw new Error("\u5FC5\u987B\u63D0\u4F9B appId \u53C2\u6570");
  const data = await callToolApi(thunkApi, "/api/version/list", { type: "app", entityId: appId }, { withAuth: true });
  if (!data.versions?.length) {
    return {
      rawData: data,
      displayData: `\u{1F4ED} \u5E94\u7528 ${appId} \u6CA1\u6709\u5386\u53F2\u7248\u672C\u5FEB\u7167\u3002`
    };
  }
  const list = data.versions.map((v, i) => {
    const date = v.createdAt ? new Date(v.createdAt).toISOString().slice(0, 16) : "?";
    const pin = v.pinned ? " \u{1F4CC}" : "";
    const label = v.label ? ` "${v.label}"` : "";
    return `${i + 1}. ${v.versionId}  ${date}${pin}${label}`;
  }).join("\n");
  return {
    rawData: data,
    displayData: `\u{1F4CB} \u5E94\u7528 ${appId} \u7684\u5386\u53F2\u7248\u672C (${data.versions.length} \u4E2A):
${list}

\u7528 appVersionRestore(appId, versionId) \u53EF\u6062\u590D\u5230\u6307\u5B9A\u7248\u672C\u3002\u5EFA\u8BAE\u5148\u6062\u590D\u6700\u8FD1\u7684\u5B8C\u6574\u7248\u672C\uFF0C\u518D\u4FEE\u6539\u3002`
  };
}
